async function loadTasks(): Promise<void> {
    dataStore.tasksState = 'loading';
    try {
        const response = await apiFetch<{ data: Array<{ text: string }> }>('/api/data/tasks', { headers: sessionHeaders() });
        dataStore.tasks = response.data;
        dataStore.tasksState = 'done';
    } catch (err) {
        const msg = err instanceof ApiError ? err.message : err instanceof Error ? err.message : 'Could not load task list';
        dataStore.tasksError = msg;
        dataStore.tasksState = 'error';
    }
}

async function loadWorksheetConfig(): Promise<string | null> {
    try {
        const config = await apiFetch<{ data: { data_panel?: { worksheet_name?: string } } | null }>('/api/config/workflow');
        return config.data?.data_panel?.worksheet_name ?? null;
    } catch { return null; }
}

The table renders `Object.keys(dataStore.worksheetRows[0])` for headers — only safe when worksheetRows.length > 0 (guarded by the {:else if dataStore.worksheetRows.length === 0} check).

dataStore is module-level singleton — shared across all component instances and mounts.

Consider: what happens on repeated mounts? What if loadWorksheetConfig() returns null due to network error vs. config not set — both silently fall to "Worksheet name not configured" error? What if result.get("tasks", []) returns non-string items? What if worksheetRows[0] has zero keys?

Output ONLY a Markdown findings list. Be adversarial.

