1	/**
2	 * Backend HTTP client. All fetch calls go through apiFetch.
3	 * Errors always surface as ApiError — never raw fetch rejections or non-2xx responses.
4	 * JSON fields from the API are snake_case; camelCase conversion happens at the call site.
5	 */
6	
7	const BACKEND_URL = (import.meta.env.VITE_BACKEND_URL as string | undefined) || 'http://localhost:8000';
8	const FETCH_TIMEOUT_MS = 10_000;
9	
10	export class ApiError extends Error {
11	  constructor(
12	    public readonly code: string,
13	    message: string,
14	    public readonly status: number,
15	  ) {
16	    super(message);
17	    this.name = 'ApiError';
18	  }
19	}
20	
21	export async function apiFetch<T>(path: string, init?: RequestInit): Promise<T> {
22	  const controller = new AbortController();
23	  const timeoutId = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
24	
25	  let response: Response;
26	  try {
27	    response = await fetch(`${BACKEND_URL}${path}`, {
28	      ...init,
29	      signal: controller.signal,
30	      headers: {
31	        'Content-Type': 'application/json',
32	        ...init?.headers,
33	      },
34	    });
35	  } catch (err) {
36	    if (err instanceof DOMException && err.name === 'AbortError') {
37	      throw new ApiError('REQUEST_TIMEOUT', 'Request timed out', 0);
38	    }
39	    throw new ApiError('NETWORK_ERROR', 'Unable to reach the autom9 backend', 0);
40	  } finally {
41	    clearTimeout(timeoutId);
42	  }
43	
44	  if (!response.ok) {
45	    let code = 'UNKNOWN_ERROR';
46	    let message = `Request failed with status ${response.status}`;
47	    try {
48	      const body = (await response.json()) as { error?: { code?: string; message?: string } };
49	      code = body?.error?.code ?? code;
50	      message = body?.error?.message ?? message;
51	    } catch {
52	      // non-JSON error body — keep defaults
53	    }
54	    throw new ApiError(code, message, response.status);
55	  }
56	
57	  try {
58	    return (await response.json()) as T;
59	  } catch {
60	    throw new ApiError('INVALID_RESPONSE', 'Server returned a non-JSON response', response.status);
61	  }
62	}
